package goemit

// nodeHTTP2DataRuntime ports Bun's incremental DATA, stream-reset, and
// content-length handling from the HTTP/2 connection engine.
const nodeHTTP2DataRuntime = `
func tsHTTP2SaturatingAddUint64(value,increment uint64)uint64{if math.MaxUint64-value<increment{return math.MaxUint64};return value+increment}
func (connection *tsHTTP2Connection)beginStreamedData(sink tsHTTP2Sink,header tsHTTP2FrameHeader,remaining []byte,padded bool)bool{payloadAvailable:=remaining[9:];padding,offset:=0,0;if padded{padding=int(payloadAvailable[0]);offset=1;if 1+padding>int(header.length){connection.sendGoAway(sink,tsHTTP2ErrorProtocol,[]byte("DATA padding too large"));return true}};dataTotal:=int(header.length)-offset-padding;connection.recvWindow.onData(int64(header.length));if connection.recvWindow.isOverflowed(){connection.sendGoAway(sink,tsHTTP2ErrorFlowControl,[]byte("connection flow-control window exceeded"));return true};if connection.streams[header.streamID]==nil&&sink.isLocalStream(header.streamID){stream:=tsHTTP2NewProtocolStream(connection.remoteSettings.initialWindowSize,connection.localSettings.initialWindowSize);stream.state=tsHTTP2StreamOpen;connection.streams[header.streamID]=stream};receiveLimit:=max(connection.ackedLocalInitialWindow,connection.localSettings.initialWindowSize);discard:=false;stream:=connection.streams[header.streamID];if stream==nil{connection.sendRstStream(sink,header.streamID,tsHTTP2ErrorStreamClosed);sink.onStreamReset(header.streamID,tsHTTP2ErrorStreamClosed);discard=true}else if !tsHTTP2CanReceiveData(stream.state){connection.sendRstStream(sink,header.streamID,tsHTTP2ErrorStreamClosed);if stream=connection.streams[header.streamID];stream!=nil{stream.state=tsHTTP2StreamClosed};sink.onStreamReset(header.streamID,tsHTTP2ErrorStreamClosed);discard=true}else{stream.recvWindow.onData(int64(header.length));if stream.recvWindow.isOverflowedWith(int64(receiveLimit)){connection.sendGoAway(sink,tsHTTP2ErrorFlowControl,[]byte("stream flow-control window exceeded"));return true};stream.recvBodyBytes=tsHTTP2SaturatingAddUint64(stream.recvBodyBytes,uint64(dataTotal))};bodyAvailable:=payloadAvailable[offset:];dataNow:=min(len(bodyAvailable),dataTotal);if dataNow>0&&!discard{sink.onData(header.streamID,bodyAvailable[:dataNow])};consumedPayload:=offset+len(bodyAvailable);connection.dataInFlight=&tsHTTP2DataInFlight{streamID:header.streamID,payloadRemaining:uint32(int(header.length)-consumedPayload),dataRemaining:uint32(dataTotal-dataNow),endStream:tsHTTP2HasFrameFlag(header.flags,1),discard:discard};connection.framesReceived++;sink.onFrameCounters(connection.framesReceived,connection.framesSent);connection.streamedDataConsumed=9+consumedPayload;return false}
func (connection *tsHTTP2Connection)finishStreamedData(sink tsHTTP2Sink,inflight *tsHTTP2DataInFlight){if !inflight.endStream||inflight.discard{return};if connection.enforceContentLength(sink,inflight.streamID){return};if stream:=connection.streams[inflight.streamID];stream!=nil{if next,err:=tsHTTP2Transition(stream.state,tsHTTP2EventRecvEndStream);err==0{stream.state=next};sink.onStreamEnd(inflight.streamID,stream.state)}}
func (connection *tsHTTP2Connection)handleData(sink tsHTTP2Sink,header tsHTTP2FrameHeader,payload []byte)bool{offset,end:=0,len(payload);if tsHTTP2HasFrameFlag(header.flags,8){if len(payload)==0{connection.sendGoAway(sink,tsHTTP2ErrorFrameSize,[]byte("DATA padded but empty"));return true};padding:=int(payload[0]);offset=1;if offset+padding>end{connection.sendGoAway(sink,tsHTTP2ErrorProtocol,[]byte("DATA padding too large"));return true};end-=padding};connection.recvWindow.onData(int64(len(payload)));if connection.recvWindow.isOverflowed(){connection.sendGoAway(sink,tsHTTP2ErrorFlowControl,[]byte("connection flow-control window exceeded"));return true};if len(payload)==0&&!tsHTTP2HasFrameFlag(header.flags,1){count:=connection.invalidFrameCount;if connection.invalidFrameCount<math.MaxUint32{connection.invalidFrameCount++};if count>connection.maxInvalidFrames{connection.terminated=true;sink.onTooManyInvalidFrames();return true}};if connection.streams[header.streamID]==nil&&sink.isLocalStream(header.streamID){stream:=tsHTTP2NewProtocolStream(connection.remoteSettings.initialWindowSize,connection.localSettings.initialWindowSize);stream.state=tsHTTP2StreamOpen;connection.streams[header.streamID]=stream};receiveLimit:=max(connection.ackedLocalInitialWindow,connection.localSettings.initialWindowSize);stream:=connection.streams[header.streamID];if stream==nil{connection.sendRstStream(sink,header.streamID,tsHTTP2ErrorStreamClosed);sink.onStreamReset(header.streamID,tsHTTP2ErrorStreamClosed);return false};if !tsHTTP2CanReceiveData(stream.state){connection.sendRstStream(sink,header.streamID,tsHTTP2ErrorStreamClosed);if stream=connection.streams[header.streamID];stream!=nil{stream.state=tsHTTP2StreamClosed};sink.onStreamReset(header.streamID,tsHTTP2ErrorStreamClosed);return false};stream.recvWindow.onData(int64(len(payload)));if stream.recvWindow.isOverflowedWith(int64(receiveLimit)){connection.sendGoAway(sink,tsHTTP2ErrorFlowControl,[]byte("stream flow-control window exceeded"));return true};stream.recvBodyBytes=tsHTTP2SaturatingAddUint64(stream.recvBodyBytes,uint64(end-offset));endStream:=tsHTTP2HasFrameFlag(header.flags,1);if end!=offset{sink.onData(header.streamID,payload[offset:end])};if endStream{if connection.enforceContentLength(sink,header.streamID){return false};if stream=connection.streams[header.streamID];stream!=nil{if next,err:=tsHTTP2Transition(stream.state,tsHTTP2EventRecvEndStream);err==0{stream.state=next};sink.onStreamEnd(header.streamID,stream.state)}};return false}
func (connection *tsHTTP2Connection)enforceContentLength(sink tsHTTP2Sink,streamID uint32)bool{if !connection.isServer{return false};stream:=connection.streams[streamID];if stream==nil||stream.contentLength==nil||*stream.contentLength==stream.recvBodyBytes{return false};connection.sendRstStream(sink,streamID,tsHTTP2ErrorProtocol);if stream=connection.streams[streamID];stream!=nil{stream.state=tsHTTP2StreamClosed};sink.onStreamReset(streamID,tsHTTP2ErrorProtocol);return true}
func (connection *tsHTTP2Connection)handleRstStream(sink tsHTTP2Sink,header tsHTTP2FrameHeader,payload []byte)bool{code:=binary.BigEndian.Uint32(payload[:4]);onIdle:=true;charged:=false;stream:=connection.streams[header.streamID];if stream!=nil&&stream.state!=tsHTTP2StreamIdle{exempt:=sink.goawaySent()&&!stream.openedAfterGoaway;charged=stream.state!=tsHTTP2StreamClosed&&!exempt;stream.state=tsHTTP2StreamClosed;onIdle=false};if onIdle&&sink.isLocalStream(header.streamID){stream=connection.streams[header.streamID];if stream==nil{stream=tsHTTP2NewProtocolStream(connection.remoteSettings.initialWindowSize,connection.localSettings.initialWindowSize);connection.streams[header.streamID]=stream};stream.state=tsHTTP2StreamClosed;onIdle=false};if onIdle&&(header.streamID<=connection.lastStreamID||header.streamID<=sink.highestStartedStreamID()){return false};if onIdle{connection.sendGoAway(sink,tsHTTP2ErrorProtocol,[]byte("RST_STREAM on idle stream"));return true};sink.onStreamReset(header.streamID,code);if charged{connection.noteReset(true)};return false}
`
